mapper.select:
SELECT l.id, l.store_id, l.product_id, p.product_code, p.product_name, p.image, l.sale_price, p.suggest_price, l.status, CASE WHEN THEN 0 ELSE 1 END AS sellable FROM prd_listing l JOIN prd_product p ON p.id = l.product_id WHERE l.store_id = #{storeId}
AND l.status = #{status}
ORDER BY l.sort, l.id

SELECT l.id AS listingId, fi.material_id AS materialId, m.material_name AS materialName, m.unit AS unit, fi.qty AS needQty, IFNULL(s.stock_qty, 0) AS stockQty FROM prd_listing l JOIN prd_product p ON p.id = l.product_id JOIN bom_formula_item fi ON fi.formula_id = p.formula_id JOIN bom_material m ON m.id = fi.material_id LEFT JOIN inv_store_material_stock s ON s.store_id = l.store_id AND s.material_id = fi.material_id WHERE l.id IN
#{id}
AND (s.stock_qty IS NULL OR s.stock_qty < fi.qty) ORDER BY l.id, fi.sort, fi.id

SELECT p.id AS productId, l.id AS listingId, p.product_name AS productName, p.category_id AS categoryId, l.sale_price AS salePrice, p.image AS image, p.description AS description FROM prd_listing l JOIN prd_product p ON p.id = l.product_id WHERE l.store_id = #{storeId} AND l.status = 1 AND p.publish_status = 1
AND p.category_id = #{categoryId}
AND NOT ORDER BY l.sort, l.id
